//! `COHPCAR.lobster` 手写解析器（LOBSTER 输出）。
//!
//! 格式（已对真实 LOBSTER 6.0 输出与 pymatgen `io.lobster.outputs.Cohpcar` 逐一核对）：
//! 1. 头部注释行（如 `ESCALE ; pCOHP file generated by LOBSTER. ...`）
//! 2. 参数行：`ncohp nspin n_energies [emin emax efermi]`
//!    - `ncohp`：相互作用数（**含**首列 `Average`）
//!    - `nspin`：2 = 自旋极化，否则 1
//!    - LOBSTER ≥ 6 在行尾追加 `emin emax efermi` 三个浮点，解析时忽略
//! 3. 标签行：自第 3 行起共 `ncohp` 行，每行一个标签，首行固定为 `Average`
//! 4. 数据行（共 `n_energies` 行）：
//!    `E  (COHP_avg, ICOHP_avg)  (COHP_1, ICOHP_1)  ...`
//!    即逐相互作用**交错**给出 (COHP, ICOHP) 列对；自旋极化时每块自旋再重复该布局
//!    （pymatgen：avg COHP = col1，bond i COHP = col(3+2i)）。
//!
//! 能量列为 LOBSTER 原始值（Fermi 已移到 0 eV），**不取负**（pymatgen `self.energies = data[0]`）。
//! 自旋极化文件当前仅解析自旋 1 块（与迁移计划一致）。

use anyhow::{bail, Context, Result};

#[derive(Debug, Clone)]
pub struct CohpCar {
    pub n_spin: usize,
    /// 相互作用标签，长度 = `ncohp`，首项为 `"Average"`。
    pub labels: Vec<String>,
    /// 能量网格（eV，Fermi 已移至 0，LOBSTER 原始值不取负）。
    pub energies: Vec<f64>,
    /// 自旋 1 COHP：`[ncohp][N]`，下标 0 为 average。
    pub cohp: Vec<Vec<f64>>,
    /// 自旋 1 ICOHP：`[ncohp][N]`，下标 0 为 average。
    pub icohp: Vec<Vec<f64>>,
}

pub fn read_cohpcarpcar(path: &str) -> Result<CohpCar> {
    let text = std::fs::read_to_string(path).with_context(|| format!("read {path}"))?;
    let lines: Vec<&str> = text.lines().collect();
    if lines.len() < 4 {
        bail!("{path} 过短，无法解析 COHPCAR.lobster");
    }

    // 参数行：`ncohp nspin n_energies [emin emax efermi]`（LOBSTER ≥ 6 行尾带浮点）
    let tokens: Vec<&str> = lines[1].split_whitespace().collect();
    if tokens.len() < 3 {
        bail!("{path} 第二行应为 `ncohp nspin n_energies [...]`");
    }
    let ncohp: usize = tokens[0]
        .parse()
        .context("第二行 ncohp 解析失败")?;
    let n_spin: usize = tokens[1]
        .parse()
        .context("第二行 nspin 解析失败")?;
    if ncohp == 0 {
        bail!("{path} 第二行 ncohp 为 0");
    }

    // 标签：自第 3 行（下标 2）起收集，直至凑满 ncohp 个（每行 1~2 个 token 均可）
    let mut labels: Vec<String> = Vec::new();
    let mut idx = 2;
    while idx < lines.len() && labels.len() < ncohp {
        let first = lines[idx].split_whitespace().next().unwrap_or("");
        if first.parse::<f64>().is_ok() {
            break; // 进入数据段
        }
        for tok in lines[idx].split_whitespace() {
            labels.push(tok.to_string());
            if labels.len() == ncohp {
                break;
            }
        }
        idx += 1;
    }
    if labels.len() != ncohp {
        bail!(
            "{path} 标签数 {} 与 ncohp={} 不一致",
            labels.len(),
            ncohp
        );
    }

    // 数据段：`E  (COHP_k, ICOHP_k) 交错`，自旋 1 块共 1 + 2*ncohp 列
    let mut energies: Vec<f64> = Vec::new();
    let mut cohp: Vec<Vec<f64>> = vec![Vec::new(); ncohp];
    let mut icohp: Vec<Vec<f64>> = vec![Vec::new(); ncohp];
    while idx < lines.len() {
        let vals: Vec<f64> = lines[idx]
            .split_whitespace()
            .filter_map(|s| s.parse::<f64>().ok())
            .collect();
        if vals.len() < 1 + 2 * ncohp {
            idx += 1;
            continue;
        }
        energies.push(vals[0]);
        for k in 0..ncohp {
            cohp[k].push(vals[1 + 2 * k]);
            icohp[k].push(vals[2 + 2 * k]);
        }
        idx += 1;
    }
    if energies.is_empty() {
        bail!("{path} 未解析到能量数据");
    }

    Ok(CohpCar {
        n_spin,
        labels,
        energies,
        cohp,
        icohp,
    })
}

/// average（首标签 `Average`）的 COHP/ICOHP 曲线。
pub fn average_cohp(car: &CohpCar) -> (Vec<f64>, Vec<f64>) {
    let idx = car
        .labels
        .iter()
        .position(|l| l.eq_ignore_ascii_case("average"))
        .unwrap_or(0);
    (car.cohp[idx].clone(), car.icohp[idx].clone())
}
